-- V90.db — Production Machine Integration + OEE Foundation
CREATE TABLE IF NOT EXISTS manufacturing_machine_status (status_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, work_center_id TEXT NOT NULL, status_code TEXT NOT NULL, reason_code TEXT, event_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, event_end TIMESTAMP, duration_minutes NUMERIC NOT NULL DEFAULT 0, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS manufacturing_machine_run (run_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, work_center_id TEXT NOT NULL, production_order_id TEXT, product_id TEXT, shift_code TEXT, planned_qty NUMERIC NOT NULL DEFAULT 0, good_qty NUMERIC NOT NULL DEFAULT 0, reject_qty NUMERIC NOT NULL DEFAULT 0, ideal_cycle_minutes NUMERIC NOT NULL DEFAULT 0, planned_minutes NUMERIC NOT NULL DEFAULT 0, actual_run_minutes NUMERIC NOT NULL DEFAULT 0, downtime_minutes NUMERIC NOT NULL DEFAULT 0, created_by TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS manufacturing_machine_oee (oee_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, work_center_id TEXT NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, planned_minutes NUMERIC NOT NULL DEFAULT 0, run_minutes NUMERIC NOT NULL DEFAULT 0, downtime_minutes NUMERIC NOT NULL DEFAULT 0, ideal_minutes NUMERIC NOT NULL DEFAULT 0, good_qty NUMERIC NOT NULL DEFAULT 0, total_qty NUMERIC NOT NULL DEFAULT 0, availability_pct NUMERIC NOT NULL DEFAULT 0, performance_pct NUMERIC NOT NULL DEFAULT 0, quality_pct NUMERIC NOT NULL DEFAULT 0, oee_pct NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'CALCULATED', approved_by TEXT, approved_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(organization_id,entity_id,work_center_id,period_start,period_end));
CREATE TABLE IF NOT EXISTS manufacturing_machine_oee_reason (reason_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, reason_code TEXT NOT NULL, reason_name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'UNPLANNED_DOWNTIME', active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(organization_id,entity_id,reason_code));
CREATE INDEX IF NOT EXISTS ix_machine_oee_run ON manufacturing_machine_run(organization_id,entity_id,work_center_id,created_at);
CREATE INDEX IF NOT EXISTS ix_machine_oee_status ON manufacturing_machine_status(organization_id,entity_id,work_center_id,event_at);
